INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2010, 'Português', 'Interpretação de texto', 'Item 1 (TPS 2010): Admissão à Carreira de Diplomata LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. | Ao receber este caderno, confira atentamente se o tipo de caderno - Caderno C-coincide com o que está registrado em sua folha de respostas e no rodapé de cada página numerada deste caderno. Em seguida, verifique se ele contém quarenta e uma questões, correspondentes à segunda etapa da prova objetiva, corretamente ordenadas de 40 a 80. 2 Quando autorizado pelo chefe de sala, no momento da identificação, escreva, no espaço apropriado da folha de respostas, com a sua caligrafia usual, a seguinte frase: Entre as dificuldades se esconde a oportunidade.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
